// Keeps the printer status from "Printer status". During a print, also asks Moonraker for the
// file's metadata, which holds the slicer's time estimate for the finish time.
msg.status = msg.statusCode === 200 ? msg.payload?.result?.status : null;
const stats = msg.status?.print_stats;
if (stats && (stats.state === 'printing' || stats.state === 'paused') && stats.filename) {
    // The http request node would send the previous response's headers with the next request.
    delete msg.headers;
    msg.url = msg.moonraker + '/server/files/metadata?filename=' + encodeURIComponent(stats.filename);
    return [msg, null];
}
return [null, msg];

// Builds the go2rtc drawtext line:
//   printing: "<clock> | Snapmaker U1 - 42.0% - 120/240 - 3:45 PM"
//   paused:   "<clock> | Snapmaker U1 - Paused - 42.0% - 120/240"
//   other:    "<clock> | Snapmaker U1"
// Everything comes from the printer's Moonraker, the same numbers as its screen.
// ffmpeg draws the clock itself (%{localtime}), in strftime format. For a 24-hour clock use '%Y-%m-%d %H:%M:%S'.
// In drawtext text, a literal % must be written as \%.
const clock = "%{localtime:'%Y-%m-%d %I:%M:%S %p'}";
const stats = msg.status?.print_stats;
const printing = stats?.state === 'printing';
const paused = stats?.state === 'paused';

const parts = [msg.printer_name || 'Snapmaker U1'];
if (printing || paused) {
    if (paused) parts.push('Paused');

    // The slicer's M73 progress, 0 to 1.
    const done = Number(msg.status.display_status?.progress);
    parts.push(Number.isFinite(done) ? `${(done * 100).toFixed(1)}\\%` : '--\\%');

    // The slicer's SET_PRINT_STATS_INFO layer counter. Left out if the file doesn't set it.
    const layer = parseInt(stats.info?.current_layer, 10);
    const total = parseInt(stats.info?.total_layer, 10);
    if (total > 0) {
        parts.push(`${Number.isFinite(layer) && layer >= 0 ? layer : 0}/${total}`);
    }

    if (printing) {
        // The slicer's estimate for the part not yet done, like the M73 time on the printer's screen.
        // Not estimate minus print_duration: that counts the calibration before layer 1 as printing,
        // and ran 5 minutes early on a 32-minute Benchy. Missing if "Slicer estimate" got no answer.
        const meta = msg.payload?.result?.filename === stats.filename ? msg.payload.result : null;
        const left = Number(meta?.estimated_time) * (1 - done);
        if (Number.isFinite(left)) {
            const finish = new Date(Date.now() + Math.max(left, 0) * 1000);
            let hours = finish.getHours();
            let minutes = finish.getMinutes();
            let ampm = hours >= 12 ? 'PM' : 'AM';
            hours = hours % 12 || 12;
            minutes = minutes.toString().padStart(2, '0');
            parts.push(`${hours}:${minutes} ${ampm}`);
        } else {
            parts.push('--:--');
        }
    }
}

msg.payload = `${clock} | ${parts.join(' - ')}`;
return msg;

// Writes the overlay line for go2rtc's ffmpeg. It goes to a temp file first and is renamed into
// place, because ffmpeg stops the stream if it reads status.txt while it's missing.
// Each write gets its own temp name: with one shared name, two writes close together could
// rename each other's file, and the second rename failed with "No such file".
const dest = '/overlay/status.txt';
const tmp = `${dest}.${Date.now()}-${Math.random().toString(36).slice(2, 8)}.tmp`;
fs.promises.writeFile(tmp, msg.payload, 'utf8')
    .then(() => fs.promises.rename(tmp, dest))
    .then(() => node.done())
    .catch(err => {
        fs.promises.unlink(tmp).catch(() => {});
        node.error(`Overlay write failed: ${err.message}`, msg);
    });
return null;
